L30_1 = "\234\183\184\235\159\180 \235\176\148\236\151\148 \236\176\168\235\157\188\235\166\172\226\128\166\226\128\166 \235\176\148\235\158\140\236\157\180 \236\134\141\236\130\173\236\151\172 \236\164\128 \234\178\176\235\167\144\236\157\180 \235\130\152\236\157\132\236\167\128\235\143\132 \235\170\168\235\166\133\235\139\136\235\139\164."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "\227\129\170\227\130\137\227\129\176\227\129\132\227\129\163\227\129\157\226\128\166\226\128\166\233\162\168\227\129\140\227\129\149\227\129\149\227\130\132\227\129\132\227\129\166\227\129\143\227\130\140\227\129\159\231\181\144\230\156\171\227\129\174\227\129\187\227\129\134\227\129\140\232\137\175\227\129\132\227\129\174\227\129\139\227\130\130\227\129\151\227\130\140\227\129\190\227\129\155\227\130\147\227\128\130"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If that\226\128\153s the case... I would rather prefer the end that the wind whispered to me."
L29_1.m_Talk_ENG = L30_1
L30_1 = "\232\136\135\229\133\182\229\166\130\230\173\164\226\128\166\233\130\163\233\162\168\232\129\178\229\145\138\232\168\180\230\136\145\231\154\132\231\181\144\229\177\128\230\136\150\232\168\177\229\165\189\228\184\128\233\187\158\227\128\130"
L29_1.m_Talk_TWN = L30_1
L30_1 = "\224\184\150\224\185\137\224\184\178\224\185\128\224\184\155\224\185\135\224\184\153\224\185\129\224\184\154\224\184\154\224\184\153\224\184\177\224\185\137\224\184\153... \224\184\137\224\184\177\224\184\153\224\184\162\224\184\180\224\184\153\224\184\148\224\184\181\224\184\158\224\184\154\224\184\129\224\184\177\224\184\154\224\184\136\224\184\184\224\184\148\224\184\136\224\184\154\224\184\151\224\184\181\224\185\136\224\184\170\224\184\178\224\184\162\224\184\165\224\184\161\224\184\129\224\184\163\224\184\176\224\184\139\224\184\180\224\184\154\224\184\154\224\184\173\224\184\129\224\184\161\224\184\178\224\184\129\224\184\129\224\184\167\224\185\136\224\184\178"
L29_1.m_Talk_THA = L30_1
L30_1 = "N\225\186\191u l\195\160 nh\198\176 v\225\186\173y... t\195\180i th\195\160 ch\225\187\141n c\195\161i k\225\186\191t th\195\186c m\195\160 gi\195\179 th\195\172 th\225\186\167m v\225\187\155i t\195\180i."
L29_1.m_Talk_VTN = L30_1
L30_1 = "\232\191\153\230\160\183\231\154\132\232\175\157\239\188\140\230\136\150\232\174\184\226\128\166\226\128\166\233\163\142\229\145\138\232\175\137\230\136\145\231\154\132\231\187\147\229\177\128\229\143\141\232\128\140\230\155\180\229\165\189\227\128\130"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wenn dem so ist ... w\195\188rde ich lieber das Ende vorziehen, das mir der Wind zugefl\195\188stert hat."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si cela devait arriver... Je pr\195\169f\195\168re encore la fin que m'a annonc\195\169e le vent."
L29_1.m_Talk_FRA = L30_1
