L31_1 = "\234\183\184 \234\178\176\235\167\144\236\157\180\235\158\128 \234\178\131\236\157\180 \235\182\128\235\148\148, \235\139\185\236\163\188\235\139\152\236\157\132 \237\149\180\236\185\152\236\167\128\235\138\148 \236\149\138\236\149\152\236\156\188\235\169\180 \236\162\139\234\178\160\234\181\176\236\154\148. \236\149\132\236\167\129 \236\151\176\237\149\169\236\155\144\235\147\164\236\151\144\234\178\144 \235\139\185\236\163\188\235\139\152\236\157\180 \237\149\132\236\154\148\237\149\152\235\139\136\234\185\140\236\154\148."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "\227\129\157\227\129\174\231\181\144\230\156\171\227\129\140\227\129\169\227\129\134\227\129\139\227\129\148\229\189\147\228\184\187\230\167\152\232\135\170\232\186\171\227\130\146\229\130\183\227\129\164\227\129\145\227\130\139\227\130\130\227\129\174\227\129\167\227\129\175\227\129\170\227\129\132\227\129\147\227\129\168\227\130\146\233\161\152\227\129\132\227\129\190\227\129\153\227\128\130\n\233\128\163\229\144\136\229\147\161\227\129\171\227\129\175\227\129\190\227\129\160\227\129\148\229\189\147\228\184\187\227\129\140\229\191\133\232\166\129\227\129\167\227\129\153\227\129\139\227\130\137\227\128\130"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I hope the end you heard doesn\226\128\153t harm you. The Alliance still needs you."
L30_1.m_Talk_ENG = L31_1
L31_1 = "\229\184\140\230\156\155\233\130\163\229\128\139\231\181\144\229\177\128\239\188\140\228\184\141\230\156\131\229\141\177\229\174\179\229\136\176\229\160\130\228\184\187\227\128\130\231\149\162\231\171\159\232\129\175\231\155\159\230\136\144\229\147\161\233\131\189\233\130\132\233\156\128\232\166\129\229\160\130\228\184\187\227\128\130"
L30_1.m_Talk_TWN = L31_1
L31_1 = "\224\184\171\224\184\167\224\184\177\224\184\135\224\184\167\224\185\136\224\184\178\224\184\136\224\184\184\224\184\148\224\184\136\224\184\154\224\184\151\224\184\181\224\185\136\224\185\132\224\184\148\224\185\137\224\184\162\224\184\180\224\184\153\224\184\153\224\184\177\224\185\136\224\184\153\224\184\136\224\184\176\224\185\132\224\184\161\224\185\136\224\184\151\224\184\179\224\185\131\224\184\171\224\185\137\224\185\128\224\184\152\224\184\173\224\185\128\224\184\155\224\185\135\224\184\153\224\184\173\224\184\177\224\184\153\224\184\149\224\184\163\224\184\178\224\184\162\224\184\153\224\184\176 \224\184\170\224\184\161\224\184\178\224\184\158\224\184\177\224\184\153\224\184\152\224\185\140\224\184\162\224\184\177\224\184\135\224\184\136\224\184\179\224\185\128\224\184\155\224\185\135\224\184\153\224\184\149\224\185\137\224\184\173\224\184\135\224\184\161\224\184\181\224\185\128\224\184\152\224\184\173"
L30_1.m_Talk_THA = L31_1
L31_1 = "T\195\180i hy v\225\187\141ng k\225\186\191t th\195\186c \196\145\195\179 kh\195\180ng l\195\160m h\225\186\161i ng\198\176\225\187\157i. Li\195\170n Minh v\225\186\171n c\225\186\167n ng\198\176\225\187\157i."
L30_1.m_Talk_VTN = L31_1
L31_1 = "\229\184\140\230\156\155\228\189\160\232\175\180\231\154\132\233\130\163\228\184\170\231\187\147\229\177\128\239\188\140\228\184\141\228\188\154\229\174\179\228\186\134\228\189\160\232\135\170\229\183\177\227\128\130\229\155\160\228\184\186\232\129\148\231\155\159\230\136\144\229\145\152\228\187\172\232\191\152\233\156\128\232\166\129\229\174\182\228\184\187\227\128\130"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich hoffe, das Ende, das Sie geh\195\182rt haben, schadet Ihnen nicht. Die Allianz braucht Sie immer noch."
L30_1.m_Talk_DEU = L31_1
L31_1 = "J'esp\195\168re simplement que cette \194\171\194\160fin\194\160\194\187 ne vous sera pas funeste. Le Clan a encore besoin de vous."
