L44_1 = "\236\150\188\234\181\180\235\185\155\236\157\180 \236\162\139\236\167\128 \236\149\138\236\138\181\235\139\136\235\139\164, \235\139\185\236\163\188\235\139\152. \236\158\165\235\161\156\235\139\152\234\187\152\236\132\156 \235\172\180\236\138\168 \235\167\144\236\148\128\236\157\180\235\157\188\235\143\132 \237\149\152\236\139\160 \234\177\180\234\176\128\236\154\148."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "\233\161\148\232\137\178\227\129\140\227\130\136\227\129\143\227\129\130\227\130\138\227\129\190\227\129\155\227\130\147\227\129\173\227\128\129\229\189\147\228\184\187\227\128\130\233\149\183\232\128\129\227\129\171\228\189\149\227\129\139\232\168\128\227\130\143\227\130\140\227\129\159\227\129\174\227\129\167\227\129\153\227\129\139\227\128\130"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You don\226\128\153t look well, Lady Nanahara. Is it because of something that the elder told you?"
L43_1.m_Talk_ENG = L44_1
